/**
 * Shapes for the persisted spend ledger.
 *
 * The ledger is append-only: an entry is written once and never edited. Money
 * is USD, rounded to 8 dp so binary-float dust does not accumulate into a cap
 * false-positive. Timestamps are ISO 8601 UTC strings; day and month
 * boundaries are computed in UTC, never in the machine's local zone, so a
 * laptop that travels does not move its own budget.
 */

/** One recorded call. `id` is generated by the ledger, never by the caller. */
export interface LedgerEntry {
  id: string;
  /** ISO 8601 timestamp of when the spend happened. */
  at: string;
  /** Model role from `services/pipeline/models.json` (`agent`, `tagging`, …). */
  role: string;
  model: string;
  listingId?: string;
  runId?: string;
  promptTokens: number;
  completionTokens: number;
  costUsd: number;
}

/** What a caller supplies. The ledger fills in `id` and defaults `at`. */
export interface RecordEntryInput {
  /** Defaults to the injected clock. */
  at?: Date | string;
  role: string;
  model: string;
  listingId?: string;
  runId?: string;
  /** Defaults to 0. */
  promptTokens?: number;
  /** Defaults to 0. */
  completionTokens?: number;
  costUsd: number;
}

/**
 * Mirrors the `budgets` block of `services/pipeline/models.json`. The ledger
 * never hardcodes these numbers; the host loads them from that file and passes
 * the object in.
 */
export interface BudgetCaps {
  monthlyCapUsd: number;
  dailyCapUsd: number;
  /** Per-listing budget for an ordinary listing. */
  perListingDefaultUsd: number;
  /** Hard ceiling for one listing, even when a larger budget was approved. */
  perListingAbsoluteUsd: number;
  /** Advisory threshold only; the ledger reports it but does not enforce it. */
  warnAtUsd?: number;
}

export interface CostSummary {
  /** Spend with a UTC date equal to the UTC date of `now`. */
  todayUsd: number;
  /** Spend in the same UTC calendar month as `now`. */
  monthUsd: number;
  /** Every entry ever recorded. */
  allUsd: number;
  /** Every entry, in append order. */
  entries: LedgerEntry[];
  /** `at` of the most recent entry, absent when the ledger is empty. */
  lastAt?: string;
}

export type CapReason = 'daily' | 'monthly' | 'listing';

export interface CapCheckInput {
  amountUsd: number;
  listingId?: string;
  /** Defaults to the injected clock. */
  now?: Date | string;
  /** Overrides the caps given to the constructor. */
  caps?: BudgetCaps;
  /**
   * Per-listing budget to apply instead of `perListingDefaultUsd`, for a
   * listing whose budget was explicitly approved. Always clamped to
   * `perListingAbsoluteUsd`.
   */
  listingCapUsd?: number;
}

export interface CapEvaluation {
  allowed: boolean;
  reason?: CapReason;
  /** Headroom before this call, per cap. Never negative. */
  remaining: {
    dailyUsd: number;
    monthlyUsd: number;
    listingUsd: number;
  };
}

export interface CostLedgerOptions {
  /** Default caps for `evaluate`; a per-call `caps` overrides them. */
  caps?: BudgetCaps;
  /** Injectable so tests never depend on the wall clock. */
  clock?: () => Date | string;
  /** Diagnostics sink. Defaults to `console.warn`. */
  warn?: (message: string) => void;
}

/** The on-disk envelope. `entries` preserves append order. */
export interface LedgerFile {
  version: 1;
  updatedAt: string;
  /** Next id sequence, persisted so ids stay unique across restarts. */
  nextSequence: number;
  entries: LedgerEntry[];
}

export type CostLedgerErrorCode = 'E_WRITE_FAILED' | 'E_INVALID_ENTRY' | 'E_BUDGET_CONFIG';
